-- -----------------------------------------------------
-- Table structure for `activity_logs`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `activity_logs`;
CREATE TABLE `activity_logs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned DEFAULT NULL,
  `username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `action` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `module` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `module` (`module`),
  KEY `idx_perf_logs` (`created_at`,`module`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------
-- Table structure for `alert`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `alert`;
CREATE TABLE `alert` (
  `id` int NOT NULL AUTO_INCREMENT,
  `judul` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `isi` text COLLATE utf8mb4_unicode_ci,
  `jenis` enum('info','warning','danger','success') COLLATE utf8mb4_unicode_ci DEFAULT 'info',
  `link` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tampil_di_frontend` tinyint(1) DEFAULT '1',
  `tampil_di_admin` tinyint(1) DEFAULT '0',
  `status` enum('aktif','nonaktif') COLLATE utf8mb4_unicode_ci DEFAULT 'aktif',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `expired_at` date DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- -----------------------------------------------------
-- Table structure for `anggota_kategorial`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `anggota_kategorial`;
CREATE TABLE `anggota_kategorial` (
  `id_anggota_kategorial` int NOT NULL AUTO_INCREMENT,
  `peran_kategorial_id` int NOT NULL,
  `umat_id` int DEFAULT NULL,
  `umat_peran_id` int DEFAULT NULL,
  `kk_id` int DEFAULT NULL,
  `paroki_id` int DEFAULT NULL,
  `stasi_kapela_id` int DEFAULT NULL,
  `wilayah_id` int DEFAULT NULL,
  `lingkungan_id` int DEFAULT NULL,
  `kub_id` int DEFAULT NULL,
  `nama_anggota` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jabatan_dalam_kelompok` enum('Koordinator','Wakil Koordinator','Sekretaris','Bendahara','Anggota','Pembina','Pendamping','Lainnya') COLLATE utf8mb4_unicode_ci DEFAULT 'Anggota',
  `tanggal_bergabung` date DEFAULT NULL,
  `tanggal_keluar` date DEFAULT NULL,
  `status_keanggotaan` enum('Aktif','Tidak Aktif','Keluar','Pindah') COLLATE utf8mb4_unicode_ci DEFAULT 'Aktif',
  `alasan_keluar` text COLLATE utf8mb4_unicode_ci,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `delete_reason` text COLLATE utf8mb4_unicode_ci,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `foto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_anggota_kategorial`),
  KEY `peran_kategorial_id` (`peran_kategorial_id`),
  KEY `umat_id` (`umat_id`),
  KEY `kk_id` (`kk_id`),
  KEY `status_keanggotaan` (`status_keanggotaan`),
  KEY `idx_anggota_is_deleted` (`is_deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

