  `wilayah_id` int DEFAULT NULL,
  `kapela_id` int DEFAULT NULL,
  `kub_id` int DEFAULT NULL,
  `level_pemilik` enum('PAROKI','STASI','WILAYAH','KUB') COLLATE utf8mb4_unicode_ci DEFAULT 'PAROKI',
  `tanggal_perolehan` date DEFAULT NULL,
  `sumber_perolehan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sumber_dana` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nilai_perolehan` decimal(15,2) DEFAULT '0.00',
  `nilai_saat_ini` decimal(15,2) DEFAULT '0.00',
  `kondisi` enum('Baik','Rusak Ringan','Rusak Berat','Hilang') COLLATE utf8mb4_unicode_ci DEFAULT 'Baik',
  `jumlah` int DEFAULT '1',
  `satuan` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `penanggung_jawab` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto_aset` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dokumen_aset` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `status_aset` enum('Aktif','Dipinjam','Dihapuskan') COLLATE utf8mb4_unicode_ci DEFAULT 'Aktif',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `qr_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `delete_reason` text COLLATE utf8mb4_unicode_ci,
  `is_deleted` tinyint(1) DEFAULT '0',
  `no_sertifikat` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_sertifikat` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'SHM/Keuskupan',
  `luas_m2` decimal(10,2) DEFAULT '0.00',
  `koordinat_gps` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `kode_aset` (`kode_aset`),
  KEY `kategori_aset_id` (`kategori_aset_id`),
  KEY `lokasi_aset` (`lokasi_aset`),
  KEY `kondisi` (`kondisi`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

