-- -----------------------------------------------------
DROP TABLE IF EXISTS `log_backup`;
CREATE TABLE `log_backup` (
  `id_backup` int NOT NULL AUTO_INCREMENT,
  `kode_backup` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipe_backup` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Database, Upload Files, Full Backup',
  `nama_file` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `path_file` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `ukuran_file` bigint DEFAULT NULL,
  `status_backup` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Berhasil' COMMENT 'Berhasil, Gagal',
  `metode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Manual' COMMENT 'Manual, Otomatis',
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `checksum` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `delete_reason` text COLLATE utf8mb4_unicode_ci,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_backup`),
  UNIQUE KEY `kode_backup` (`kode_backup`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- (Data for `log_backup` is intentionally empty for new parish installation)

