-- -----------------------------------------------------
-- Table structure for `stasis`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `stasis`;
CREATE TABLE `stasis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `paroki_id` bigint unsigned NOT NULL,
  `kode` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipe` enum('Stasi','Kapela') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Stasi',
  `pelindung` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provinsi_kode` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kabupaten_kode` char(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kecamatan_kode` char(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `desa_kode` char(13) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alamat` text COLLATE utf8mb4_unicode_ci,
  `is_aktif` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `stasis_paroki_id_foreign` (`paroki_id`),
  KEY `stasis_provinsi_kode_foreign` (`provinsi_kode`),
  KEY `stasis_kabupaten_kode_foreign` (`kabupaten_kode`),
  KEY `stasis_kecamatan_kode_foreign` (`kecamatan_kode`),
  KEY `stasis_desa_kode_foreign` (`desa_kode`),
  KEY `stasis_kode_index` (`kode`),
  CONSTRAINT `stasis_desa_kode_foreign` FOREIGN KEY (`desa_kode`) REFERENCES `wilayah_desas` (`kode`) ON DELETE SET NULL,
  CONSTRAINT `stasis_kabupaten_kode_foreign` FOREIGN KEY (`kabupaten_kode`) REFERENCES `wilayah_kabupatens` (`kode`) ON DELETE SET NULL,
  CONSTRAINT `stasis_kecamatan_kode_foreign` FOREIGN KEY (`kecamatan_kode`) REFERENCES `wilayah_kecamatans` (`kode`) ON DELETE SET NULL,
  CONSTRAINT `stasis_paroki_id_foreign` FOREIGN KEY (`paroki_id`) REFERENCES `parokis` (`id`) ON DELETE CASCADE,
  CONSTRAINT `stasis_provinsi_kode_foreign` FOREIGN KEY (`provinsi_kode`) REFERENCES `wilayah_provinsis` (`kode`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


