-- -----------------------------------------------------
-- Table structure for `wilayahs`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `wilayahs`;
CREATE TABLE `wilayahs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `paroki_id` bigint unsigned NOT NULL,
  `kode` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nomor_wilayah` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_koordinator` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provinsi_kode` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kabupaten_kode` char(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kecamatan_kode` char(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `desa_kode` char(13) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_aktif` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `wilayahs_paroki_id_foreign` (`paroki_id`),
  KEY `wilayahs_provinsi_kode_foreign` (`provinsi_kode`),
  KEY `wilayahs_kabupaten_kode_foreign` (`kabupaten_kode`),
  KEY `wilayahs_kecamatan_kode_foreign` (`kecamatan_kode`),
  KEY `wilayahs_desa_kode_foreign` (`desa_kode`),
  KEY `wilayahs_kode_index` (`kode`),
  CONSTRAINT `wilayahs_desa_kode_foreign` FOREIGN KEY (`desa_kode`) REFERENCES `wilayah_desas` (`kode`) ON DELETE SET NULL,
  CONSTRAINT `wilayahs_kabupaten_kode_foreign` FOREIGN KEY (`kabupaten_kode`) REFERENCES `wilayah_kabupatens` (`kode`) ON DELETE SET NULL,
  CONSTRAINT `wilayahs_kecamatan_kode_foreign` FOREIGN KEY (`kecamatan_kode`) REFERENCES `wilayah_kecamatans` (`kode`) ON DELETE SET NULL,
  CONSTRAINT `wilayahs_paroki_id_foreign` FOREIGN KEY (`paroki_id`) REFERENCES `parokis` (`id`) ON DELETE CASCADE,
  CONSTRAINT `wilayahs_provinsi_kode_foreign` FOREIGN KEY (`provinsi_kode`) REFERENCES `wilayah_provinsis` (`kode`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


